public class Question_15{public static void main(String[]x){String route="CHN-BLR / CBE / BLR-CHN";StringBuilder c=new StringBuilder();for(char v:route.toUpperCase().toCharArray())if(Character.isLetterOrDigit(v))c.append(v);int l=0,r=c.length()-1;boolean ok=true;while(l<r){if(c.charAt(l)!=c.charAt(r)){ok=false;break;}l++;r--;}System.out.println("Normalised route: "+c);System.out.println("Palindrome: "+ok);}}